              <div className="art:relative art:z-10 art:flex art:min-w-0 art:max-w-lg art:flex-col art:items-start">
                <p className="art:flex art:items-center art:gap-2.5 art:text-xs art:font-medium art:text-muted-foreground">
                  <span aria-hidden="true" className="art:size-1.5 art:shrink-0 art:rounded-full art:bg-primary"/>
                  {copy.badge}
                </p>
                <h2 id={`${artemisInstanceId}-graphic`} className="art:mt-7 art:text-balance art:text-4xl art:font-medium art:leading-tight art:tracking-tight">
                  <span className="art:block">
                    {copy.headline}
                  </span>
                  {accent ? (<span className="art:block art:text-muted-foreground">
                      {accent}
                    </span>) : null}
                </h2>
                <p className="art:mt-5 art:max-w-md art:text-pretty art:text-sm art:leading-relaxed art:text-muted-foreground art:@min-[640px]/artemis:text-base">
                  {copy.subhead}
                </p>
                <div className="art:mt-8 art:flex art:w-full art:flex-col art:gap-3 art:@min-[640px]/artemis:w-auto art:@min-[640px]/artemis:flex-row art:@min-[640px]/artemis:flex-wrap">
                  <motion.a whileHover={reduce ? undefined : { scale: 1.01 }} whileTap={reduce ? undefined : { scale: 0.99 }} transition={ARTEMIS_SPRING_PRESS} className="art:inline-flex art:items-center art:justify-center art:font-medium art:select-none art:transition-colors art:disabled:pointer-events-none art:disabled:opacity-50 art:bg-primary art:text-primary-foreground art:hover:bg-primary/90 art:gap-2 art:px-5 art:text-sm art:focus-visible:outline-none art:focus-visible:ring-2 art:focus-visible:ring-ring art:focus-visible:ring-offset-2 art:focus-visible:ring-offset-background art:relative art:h-9 art:after:absolute art:after:inset-x-0 art:after:-inset-y-1 art:focus-visible:outline-2 art:focus-visible:outline-offset-4 art:focus-visible:outline-ring art:rounded-full" href={copy.cta.href} tabIndex={0}>
                    {copy.cta.label}
                    <svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" className="art:lucide art:lucide-arrow-right art:size-4" aria-hidden="true">
                      <path d="M5 12h14"/>
                      <path d="m12 5 7 7-7 7"/>
                    </svg>
                  </motion.a>
                  <motion.a whileHover={reduce ? undefined : { scale: 1.01 }} whileTap={reduce ? undefined : { scale: 0.99 }} transition={ARTEMIS_SPRING_PRESS} className="art:inline-flex art:items-center art:justify-center art:font-medium art:select-none art:transition-colors art:disabled:pointer-events-none art:disabled:opacity-50 art:border art:border-border art:bg-transparent art:text-foreground art:hover:bg-primary/5 art:gap-2 art:px-5 art:text-sm art:focus-visible:outline-none art:focus-visible:ring-2 art:focus-visible:ring-ring art:focus-visible:ring-offset-2 art:focus-visible:ring-offset-background art:relative art:h-9 art:after:absolute art:after:inset-x-0 art:after:-inset-y-1 art:focus-visible:outline-2 art:focus-visible:outline-offset-4 art:focus-visible:outline-ring art:rounded-full" href={copy.secondaryCta.href} tabIndex={0}>
                    {copy.secondaryCta.label}
                    <svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" className="art:lucide art:lucide-arrow-up-right art:size-4" aria-hidden="true">
                      <path d="M7 7h10v10"/>
                      <path d="M7 17 17 7"/>
                    </svg>
                  </motion.a>
                </div>
                <p className="art:mt-5 art:flex art:items-center art:gap-2 art:text-xs art:leading-relaxed art:text-muted-foreground">
                  <svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" className="art:lucide art:lucide-check art:size-3.5 art:shrink-0" aria-hidden="true">
                    <path d="M20 6 9 17l-5-5"/>
                  </svg>
                  {copy.note}
                </p>
              </div>
              <div className="art:aspect-[4/3] art:w-full art:overflow-hidden art:rounded-2xl art:border art:border-border">
                <img src={copy.image.src} alt={copy.image.alt} width="1000" height="750" loading="lazy" decoding="async" className="art:size-full art:object-cover"/>
              </div>
            </div>
            <div className="art:flex art:flex-wrap art:items-center art:justify-center art:gap-x-7 art:gap-y-2 art:border-t art:border-border art:px-6 art:py-4 art:text-xs art:text-muted-foreground art:@min-[640px]/artemis:justify-start art:@min-[640px]/artemis:px-10 art:@min-[1024px]/artemis:px-14">
              {copy.highlights.map((text) => (<span key={text}>
                  {text}
                </span>))}
            </div>
          </div>
        </section>
      </div>
    </>);
}
